documents.aggregate_windows:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID, SEQ]
input:
  CLINIC: {path: clinic.csv, types: {SEQ: int, DAY: int}}
  HOME: {path: home.csv, types: {SEQ: int, DAY: int}}
  WINDOWS: {path: windows.csv, key: [STUDYID], types: {LO: int, HI: int}}
output: {path: out.csv, columns: [STUDYID, USUBJID, SEQ, HOLDING]}
columns:
  - {name: STUDYID, type: str}
  - {name: USUBJID, type: str}
  - {name: SEQ, type: int}
  - name: HOLDING
    type: int
    derivation:
      aggregate:
        between: {value: HOME.DAY, lower: LO, upper: HI}
        expr: "COUNT(WINDOWS.*)"
rows:
  - id: home
    dataset: HOME
    derivations:
      STUDYID: HOME.STUDYID
      USUBJID: HOME.USUBJID
      SEQ: HOME.SEQ

