documents.nearest_ecgs:
yamaa: "1.0"
type: spec
domain: OUT
keys: [STUDYID, USUBJID, EGSEQ]
input:
  EG: {path: eg.csv, types: {EGSEQ: int, EGDTC: datetime}}
  PC: {path: pc.csv, types: {PCSEQ: int, PCDTM: datetime}}
base: EG
output: {path: out.csv, columns: [STUDYID, USUBJID, EGSEQ, PCSEQ]}
intermediates:
  - id: NEAR
    dataset: PC
    key: [STUDYID, USUBJID]
    nearest: {source: PCDTM, to: EG.EGDTC, unit: hour}
columns:
  - {name: STUDYID, type: str, derivation: EG.STUDYID}
  - {name: USUBJID, type: str, derivation: EG.USUBJID}
  - {name: EGSEQ, type: int, derivation: EG.EGSEQ}
  - {name: ADTM, type: datetime, derivation: EG.EGDTC}
  - {name: PCSEQ, type: int, derivation: NEAR.PCSEQ}

