documents.grouped_lookups:
yamaa: "1.0"
type: spec
domain: OUT
keys: [GRP]
input:
  SRC: {path: source.csv, types: {ID: int, VAL: int}}
  DONOR: {path: donor.csv, types: {KEY: int, X: int}}
  WIN: {path: win.csv, types: {ID: int, LO: int, HI: int}}
output: {path: out.csv, columns: [GRP, VALUE]}
intermediates:
  - id: P
    dataset: DONOR
    key: {KEY: SRC.ID}
columns:
  - {name: GRP, type: str}
  - {name: VALUE, type: str}
rows:
  - id: grouped
    dataset: SRC
    group_by: [SRC.GRP]
    derivations:
      GRP: SRC.GRP
      VALUE: P.X

documents.verified_lookup:
yamaa: "1.0"
type: spec
domain: OUT
keys: [ID]
input:
  SRC: {path: source.csv, types: {ID: int, VAL: int}}
  DONOR: {path: donor.csv, types: {KEY: int, X: int}}
  WIN: {path: win.csv, types: {ID: int, LO: int, HI: int}}
base: SRC
output: {path: out.csv, columns: [ID]}
intermediates:
  - id: P
    dataset: DONOR
    key: {KEY: ID}
columns:
  - {name: ID, type: int, derivation: SRC.ID}
verifications:
  - assert:
      id: positive
      require: 'P.X > 0'

documents.lookup_read_twice:
yamaa: "1.0"
type: spec
domain: OUT
keys: [ID, ORIGIN]
input:
  SRC: {path: source.csv, types: {ID: int, VAL: int}}
  DONOR: {path: donor.csv, types: {KEY: int, X: int}}
  WIN: {path: win.csv, types: {ID: int, LO: int, HI: int}}
output: {path: out.csv, columns: [ID, ORIGIN, VALUE]}
intermediates:
  - id: P
    dataset: WIN
    key: {ID: 1}
    filter: 'WIN.HI < SRC.VAL'
    order_by: [WIN.LO]
    keep: first
columns:
  - {name: ID, type: int}
  - {name: ORIGIN, type: str}
  - {name: VALUE, type: str, derivation: P.NAME}
rows:
  - id: first
    dataset: SRC
    derivations: {ID: SRC.ID, ORIGIN: "'A'"}

  - id: second
    dataset: SRC
    derivations: {ID: SRC.ID, ORIGIN: "'B'"}

documents.named_absence:
yamaa: "1.0"
type: spec
domain: ADAE
keys: [STUDYID, USUBJID, AESEQ]
input:
  AE: ae.csv
  ADSL: {path: adsl.csv, key: [STUDYID, USUBJID], types: {AGE: int}}
base: AE
output:
  path: adae.csv
  columns: [STUDYID, USUBJID, AESEQ, TRTSDT, ARM, ARMD, AGE1]
intermediates:
  - {id: SAFETY, dataset: ADSL, key: [STUDYID, USUBJID], filter: "ADSL.SAFFL = 'Y'"}
  - {id: NAMED, dataset: ADSL, key: [STUDYID, USUBJID], filter: "ADSL.SAFFL = 'Y'", absent: NONE}
columns:
  - {name: STUDYID, type: str, derivation: AE.STUDYID}
  - {name: USUBJID, type: str, derivation: AE.USUBJID}
  - {name: AESEQ, type: int, derivation: AE.AESEQ}
  - {name: TRTSDT, type: str, derivation: ADSL.TRTSDT}
  - {name: ARM, type: str, derivation: SAFETY.ARM}
  - {name: ARMD, type: str, derivation: NAMED.ARM}
  - {name: AGE1, type: int, derivation: "SAFETY.AGE + 1"}

